                                    "dependencies": {
                                      "items": {
                                        "minLength": 1,
                                        "type": "string"
                                      },
                                      "type": "array"
                                    },
                                    "kind": {
                                      "const": "source",
                                      "type": "string"
                                    },
                                    "language": {
                                      "enum": [
                                        "javascript",
                                        "typescript"
                                      ],
                                      "type": "string"
                                    },
