                        }
                      },
                      "required": [
                        "target",
                        "resource"
                      ],
                      "type": "object"
                    },
                    {
                      "additionalProperties": false,
                      "properties": {
                        "asset": {
                          "maxLength": 100,
                          "minLength": 1,
                          "type": "string"
                        },
                        "fit": {
                          "enum": [
                            "contain",
                            "cover",
                            "stretch"
                          ],
                          "type": "string"
                        },
                        "target": {
                          "maxLength": 100,
                          "minLength": 1,
